import React from 'react';

function CartPage({ cart, onClearCart, onPlaceOrder }) {
    const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const handlePlaceOrder = () => {
        if (onPlaceOrder) {
            onPlaceOrder();
        }
    };

    return (
        <div className="bg-gray-50 min-h-screen p-6">
            <h1 className="text-4xl font-bold text-center text-green-600 mb-6">
                Your Cart
            </h1>
            {cart.length === 0 ? (
                <p className="text-center text-lg text-gray-500">
                    Your cart is empty. Add some products!
                </p>
            ) : (
                <>
                    <div className="max-w-4xl mx-auto">
                        <div className="grid gap-6">
                            {cart.map((item) => (
                                <div
                                    key={item.id}
                                    className="flex items-center justify-between bg-white p-4 rounded-lg shadow-md"
                                >
                                    <div className="flex items-center space-x-4">
                                        <img
                                            src={item.image}
                                            alt={item.name}
                                            className="w-20 h-20 object-cover rounded-lg"
                                        />
                                        <div>
                                            <h3 className="text-lg font-semibold text-gray-800">
                                                {item.name}
                                            </h3>
                                            <p className="text-gray-500">
                                                ${item.price} x {item.quantity}
                                            </p>
                                        </div>
                                    </div>
                                    <p className="text-lg font-bold text-green-600">
                                        ${item.price * item.quantity}
                                    </p>
                                </div>
                            ))}
                        </div>
                        <div className="mt-8 p-4 bg-white rounded-lg shadow-md">
                            <h2 className="text-xl font-bold text-gray-800">
                                Total: <span className="text-green-600">${totalAmount.toFixed(2)}</span>
                            </h2>
                            <button
                                onClick={handlePlaceOrder}
                                className="mt-4 w-full bg-green-500 text-white py-3 px-6 rounded-lg font-semibold hover:bg-green-600 transition duration-200"
                            >
                                Place Order
                            </button>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
}

export default CartPage;
